# GET /api/sheets/{sheetId}/tags — every tag ever carried by a claim of the sheet, sorted (["a","b"]).
respond:
  class: net.officefloor.hq.app.claim.RespondWithTags
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithTags {
    public void respond(@PathVariable("sheetId") String sheetId, Claims claims, ObjectResponse<List<String>> response) {
        response.send(claims.tagsUsed(sheetId.trim()));
    }
}
import { useQuery } from '@tanstack/react-query';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery, counts, tagsQuery } from '../claims/claimsQuery';
import { peopleQuery } from '../people/peopleQuery';
import { figure, ratesQuery, sumDue } from '../rates/ratesQuery';
import { useFloor, useLate } from '../settings/settingsQuery';
import { useSheetToday } from '../sheet/useSheetToday';

/**
 * A due-total per tag, for every tag ever used on the sheet: the figures of the claims that count which carry it, or
 * whose person carries it, added up (n/a skipped; not capped) — a claim once per tag. A claim with two tags counts in both.
 */
function TagTotals({ sheetId }: { sheetId: string }) {
  const tags = useQuery(tagsQuery(sheetId)).data ?? [];
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const rates = useQuery(ratesQuery(sheetId)).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const counting = claims.filter((c) => counts(c, people, today));

  return (
    <table data-testid="tag-totals">
      <thead>
        <tr>
          <th>Tag</th>
          <th>Due</th>
        </tr>
      </thead>
      <tbody>
        {tags.map((t) => (
          <tr key={t} data-testid={`tag-${t}`}>
            <td>{t}</td>
            <td data-testid={`tag-${t}-due-total`}>
              {sumDue(counting
                .filter((c) => c.tags.includes(t) || people.find((p) => p.id === c.personId)?.tags.includes(t))
                .map((c) => figure(c, rates, people.find((p) => p.id === c.personId), floor, late)))}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export const contribution = SheetPanel.fill({ order: 26, Component: TagTotals });
